(() => {
  'use strict';
  const data=window.FAMILY_DATA, home=data.home;
  const categories={all:{label:'全部',symbol:'✳',color:'#174e42'},school:{label:'小学',symbol:'校',color:'#a44319'},spanish:{label:'西班牙语',symbol:'ES',color:'#bb5837'},english:{label:'英语',symbol:'EN',color:'#416cc0'},course:{label:'儿童课程',symbol:'✦',color:'#8852a8'},indoor:{label:'室内好去处',symbol:'▧',color:'#b47c16'},outdoor:{label:'户外玩耍',symbol:'♧',color:'#39856e'}};
  const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let category='all',scope='all',selected=null,map=null,markerLayer=null;
  function distance(p){const r=Math.PI/180,a=(p.lat-home.lat)*r,b=(p.lng-home.lng)*r;return 6371*2*Math.asin(Math.sqrt(Math.sin(a/2)**2+Math.cos(home.lat*r)*Math.cos(p.lat*r)*Math.sin(b/2)**2));}
  data.places.forEach(p=>{p.km=distance(p);p.walk=Math.max(3,Math.ceil(p.km*1.3/3.5*60));});
  const filtered=()=>data.places.filter(p=>(category==='all'||p.cat===category)&&(scope==='all'||scope==='near'&&p.walk<=20||scope==='extended'&&p.walk>20&&!p.special||scope==='special'&&p.special)).sort((a,b)=>a.km-b.km);
  function googlePlace(p){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.original+', '+p.address+', Barcelona');}
  function directions(p,mode='walking'){return 'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(home.address+', Barcelona')+'&destination='+encodeURIComponent(p.navigation||p.original+', '+p.address+', Barcelona')+'&travelmode='+mode;}
  function initMap(){if(!window.L){$('#map-error').hidden=false;return;}map=L.map('map',{zoomControl:false,scrollWheelZoom:true}).setView([home.lat-.002,home.lng],15);L.control.zoom({position:'topright'}).addTo(map);let failed=0;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).on('tileerror',()=>{if(++failed>3)$('#map-error').hidden=false;}).on('tileload',()=>{$('#map-error').hidden=true;failed=0;}).addTo(map);L.circle([home.lat,home.lng],{radius:800,color:'#557969',weight:1.5,dashArray:'5,7',fillOpacity:.035,interactive:false}).addTo(map);L.marker([home.lat,home.lng],{icon:L.divIcon({className:'map-marker home-marker',html:'⌂',iconSize:[24,24],iconAnchor:[12,12]}),title:'家 · '+home.address,zIndexOffset:-1000}).addTo(map).bindTooltip('家 · '+esc(home.address));markerLayer=L.layerGroup().addTo(map);}
  function render(fit=false){$('#categories').innerHTML=Object.entries(categories).map(([k,c])=>`<button class="category" data-category="${k}" aria-pressed="${category===k}" style="--category-color:${c.color}"><span class="category-symbol" aria-hidden="true">${c.symbol}</span>${c.label}</button>`).join('');$('#scope').value=scope;const places=filtered();$('#list-title').textContent={near:'家附近的发现',extended:'周边再走远一点',special:'值得专程去',all:'探索整个巴塞罗那'}[scope];const total=data.places.filter(p=>category==='all'||p.cat===category).length;$('#result-count').innerHTML=`当前 ${places.length} / 已收录 ${total} 个 · ${categories[category].label}${places.length<total?' <button id="expand-scope" class="expand-scope">查看全部范围</button>':''}`;const note=$('#category-note');note.hidden=!['spanish','school'].includes(category);note.innerHTML='<strong>6岁西语：先看距离，再问上课形式</strong><p>地图现有4处西语候选。附近优先问 Ausfun；Dime 有儿童专课及6岁案例，粗估21分钟步行，默认全范围可直接查看。Spanish Horizons 为儿童课，Languages4Life 为亲子定制。</p><details><summary>另有3种上门 / 线上选择</summary><p>以下服务不计入地图地点数，无已核实的固定上课地址。</p><p><a href="https://www.e-dill.com/3s/index.php/cursos/idiomas-para-ninos-y-adolescentes" target="_blank" rel="noopener">E-dill · 儿童上门西语</a><br>官网确认巴塞罗那儿童上门课及西语作为外语；6岁接收、Hurtado服务范围、价格待询。联系 info@e-dill.com。未使用旧目录里的Balmes校址和课表。</p><p><a href="https://speakspanishbarcelona.com/" target="_blank" rel="noopener">Speak Spanish Barcelona · 上门 / 线上</a><br>官网有Spanish for kids，上门单人35欧/小时、10小时320欧；儿童是否适用此报价、6岁教学及服务范围待确认。电话657 478 602。</p><p><a href="https://www.trainlang.com/clases/espanol/?para=ninos&amp;ubicacion=barcelona" target="_blank" rel="noopener">Trainlang · 儿童线上西语</a><br>官网写4–5岁起、视频一对一，可先试课；课程时长、付款周期与价格须核对。它是线上课程，网页提及Barcelona不代表有本地教室。</p></details><details><summary>咨询时优先问什么？</summary><p>能否教6岁西语初学者？是现成同龄小班、自己组两人班还是一对一？每次能否先从30–45分钟开始？教师是否有低龄儿童西语经验？是否可试课、家长能否陪同、总费用及取消规则是什么？</p><p>本次未把成人西语班、仅用西语教学的美术课、学校内部支援或已结束的夏令营算作当前儿童语言班。所有空位均未电话确认。</p></details>';if(category==='school'){note.innerHTML='<strong>小学清单 · 9所半公半私 / 3所私立</strong><p>重点关注（非质量排名）：</p><div class="school-shortcuts">'+data.places.filter(p=>p.priority).sort((a,b)=>a.priority-b.priority).map(p=>`<button data-school-id="${p.id}">★ ${esc(p.name)}</button>`).join('')+'</div><p>列表仍按离家远近排序。Concertado为私立办学、相应阶段获公共资助；国际学校年级划分可能不同。招生名额、语言支持和费用均待学校确认。</p><small>学校资料核查：2026-09-30 · 近邻及周边候选，非全城完整名录</small>';if(scope!=='all')note.innerHTML+='<p>当前范围可能隐藏部分学校，请切换“全部地点”查看12所。</p>'; };$('#cards').innerHTML=places.length?places.map(p=>{const c=categories[p.cat];return `<button class="place-card ${p.priority?'priority-school':''} ${selected===p.id?'selected':''}" data-id="${esc(p.id)}" style="--category-color:${c.color}"><div class="card-top"><span class="tag"><span aria-hidden="true">${c.symbol}</span>${esc(p.type)}</span><span class="walk">${p.walk<=35?'步行约 '+p.walk+' 分钟':'直线 '+p.km.toFixed(1)+' km'}</span></div><h3>${p.priority?'<span class="priority-badge">★ 重点关注</span>':''}${esc(p.name)}</h3><p class="original">${esc(p.original)}</p><p class="summary">${esc(p.summary)}</p>${p.originLabel?`<p class="origin-label">${esc(p.originLabel)}</p>`:''}<div class="card-foot"><span>${esc(p.price)}</span><span class="status ${p.pending?'pending':''}">${esc(p.status)}</span></div></button>`;}).join(''):`<div class="empty">这个范围内暂未收录${category==='all'?'地点':esc(categories[category].label)}。<br>可以扩大范围，看看其他候选地点。<button id="show-all">查看全城${category==='all'?'地点':esc(categories[category].label)}</button></div>`;if(markerLayer){markerLayer.clearLayers();places.forEach(p=>{const c=categories[p.cat];L.marker([p.lat,p.lng],{icon:L.divIcon({className:'map-marker'+(p.priority?' priority-marker':''),html:`<span style="background:${c.color};width:100%;height:100%;border-radius:50%;display:grid;place-items:center">${p.priority?'★':c.symbol}</span>`,iconSize:[35,35],iconAnchor:[17,17]}),title:p.name,alt:p.name,riseOnHover:true}).addTo(markerLayer).bindTooltip(esc(p.name),{direction:'top',offset:[0,-17],permanent:category==='school'&&!!p.priority}).on('click',()=>openPlace(p.id));});if(fit&&places.length){const bounds=L.latLngBounds([[home.lat,home.lng],...places.map(p=>[p.lat,p.lng])]);map.fitBounds(bounds,{padding:[55,55],maxZoom:15,animate:false});}}}
  function openPlace(id){const p=data.places.find(p=>p.id===id);if(!p)return;selected=id;render();if(map)map.panTo([p.lat,p.lng],{animate:false});const c=categories[p.cat];$('#detail-content').innerHTML=`<div class="tag detail-tag" style="--category-color:${c.color}">${p.priority?'★ 重点关注 · ':''}${c.symbol} ${esc(categories[p.cat].label)} · ${p.special?'值得专程去':p.walk<=20?'家附近':'周边扩展'}</div><h2 id="detail-title" class="detail-title">${esc(p.name)}</h2><p class="original">${esc(p.original)}</p><p class="detail-summary">${esc(p.summary)}</p><dl class="detail-grid">${p.cat==='school'?`<dt>办学类型</dt><dd>${p.schoolType==='concertado'?'半公半私（concertado）':'私立（非concertado）'}</dd>`:''}<dt>适龄</dt><dd>${esc(p.age)}</dd><dt>费用</dt><dd>${esc(p.priceDetail||p.price)}</dd><dt>时间</dt><dd>${esc(p.schedule)}</dd><dt>地址</dt><dd>${esc(p.address)}</dd><dt>路程</dt><dd>直线约 ${p.km.toFixed(2)} km${p.walk<=45?' · 步行粗估 '+p.walk+' 分钟':''}<br>按直线距离 × 1.3、时速3.5公里估算；不含坡度与具体入口，请打开导航确认。</dd></dl><div class="detail-note">${esc(p.note)}</div><div class="detail-actions"><a href="${directions(p)}" target="_blank" rel="noopener">步行导航</a><a class="secondary" href="${directions(p,'transit')}" target="_blank" rel="noopener">公共交通</a><a class="secondary google-place-link" href="${googlePlace(p)}" target="_blank" rel="noopener">在 Google 地图查看</a>${p.website?`<a class="secondary" href="${esc(p.website)}" target="_blank" rel="noopener">查看官网</a>`:''}</div>${p.originLabel?`<section class="origin-details"><strong>${esc(p.originLabel)}（用户截图）</strong><p>${esc(p.originNote)}</p>${p.historicalNote?`<details class="historical-info"><summary>历史活动 · 已结束</summary><p>${esc(p.historicalNote)}</p></details>`:''}</section>`:''}<p class="source-title">信息来源 · 可自行核对</p><ul class="source-list">${p.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)}</a></li>`).join('')}</ul><p class="detail-meta">资料核查：${p.checked||data.checked} · ${esc(p.status)}<br>课程空位未确认；费用与开放时间可能调整。${p.geoLabel?'<br>地图定位：'+esc(p.geoLabel):''}</p>`;if(!$('#details').open)$('#details').showModal();$('#details').scrollTop=0;}
  $('#category-note').addEventListener('click',e=>{const b=e.target.closest('[data-school-id]');if(b){const p=data.places.find(p=>p.id===b.dataset.schoolId);if(!filtered().includes(p))scope='all';openPlace(b.dataset.schoolId);}});
  $('#result-count').addEventListener('click',e=>{if(e.target.closest('#expand-scope')){scope='all';render(true);}});$('#doorstep-button').addEventListener('click',()=>{if(map)map.setView([home.lat,home.lng],19,{animate:false});});$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;selected=null;render(true);}});$('#scope').addEventListener('change',e=>{scope=e.target.value;selected=null;render(true);});$('#cards').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)openPlace(b.dataset.id);else if(e.target.closest('#show-all')){scope='all';render(true);}});$('#close-details').addEventListener('click',()=>$('#details').close());$('#details').addEventListener('click',e=>{if(e.target===$('#details')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});document.querySelectorAll('.checked-date').forEach(e=>e.textContent=data.checked);initMap();render(true);
  if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_family_places',title:'筛选亲子地图',description:'按类别和范围筛选地图与地点列表；不报名、不预约。',inputSchema:{type:'object',properties:{category:{type:'string',enum:Object.keys(categories)},scope:{type:'string',enum:['near','extended','special','all']}},required:['category','scope'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Object.hasOwn(categories,input.category)||!['near','extended','special','all'].includes(input.scope)||Object.keys(input).some(k=>!['category','scope'].includes(k)))throw new Error('无效类别或范围');category=input.category;scope=input.scope;selected=null;render(true);return {category,scope,places:filtered().map(p=>({id:p.id,name:p.name,status:p.status}))};}})).catch(()=>{});}catch{}}
})();
